ALTER TABLE "Document" ADD COLUMN "credited" DECIMAL(18,2) NOT NULL DEFAULT 0;
ALTER TABLE "Document" DROP CONSTRAINT "document_money_valid";
ALTER TABLE "Document" ADD CONSTRAINT "document_money_valid" CHECK ("paid">=0 AND "credited">=0 AND "paid"+"credited"<="total" AND "total">=0);
CREATE TABLE "CreditNote"("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"invoiceId" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL CHECK("amount">0),"reason" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "CreditNote_organizationId_idempotencyKey_key" ON "CreditNote"("organizationId","idempotencyKey");
CREATE INDEX "CreditNote_organizationId_invoiceId_idx" ON "CreditNote"("organizationId","invoiceId");
CREATE TABLE "TaxRate"("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"rate" DECIMAL(8,4) NOT NULL CHECK("rate">=0 AND "rate"<=100),"active" BOOLEAN NOT NULL DEFAULT true,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "TaxRate_organizationId_active_idx" ON "TaxRate"("organizationId","active");
CREATE INDEX "Document_organizationId_kind_createdAt_idx" ON "Document"("organizationId","kind","createdAt");
CREATE INDEX "Expense_organizationId_projectId_idx" ON "Expense"("organizationId","projectId");
CREATE INDEX "Task_organizationId_dueDate_idx" ON "Task"("organizationId","dueDate");
CREATE INDEX "Customer_organizationId_createdAt_idx" ON "Customer"("organizationId","createdAt");
CREATE INDEX "Product_organizationId_createdAt_idx" ON "Product"("organizationId","createdAt");
CREATE INDEX "InventoryMovement_receipt_idx" ON "InventoryMovement"("organizationId","kind","reference","productId");
CREATE INDEX "Customer_organizationId_lower_name_idx" ON "Customer"("organizationId",lower(name));
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX "Product_name_search_idx" ON "Product" USING gin(name gin_trgm_ops);
CREATE INDEX "Product_sku_search_idx" ON "Product" USING gin(sku gin_trgm_ops);
CREATE INDEX "Customer_name_search_idx" ON "Customer" USING gin(name gin_trgm_ops);
CREATE INDEX "Inquiry_subject_search_idx" ON "Inquiry" USING gin(subject gin_trgm_ops);
CREATE INDEX "Inquiry_text_search_idx" ON "Inquiry" USING gin(text gin_trgm_ops);
